from zookeeper.core.component import component, configure
from zookeeper.core.field import Field, ComponentField

@component
class Child:
    a: int = Field(4)

@component
class Parent:
    a: int = Field(2)
    child: Child = ComponentField()

    def __pre_configure__(self, conf):
        if 'a' in conf:
            return {'child.a': conf['a'] * 7, **conf}
        return conf

parent = Parent()
configure(parent, {'a': 6})
assert parent.a == 6, f'Expected 6, got {parent.a}'
assert parent.child.a == 42, f'Expected 42, got {parent.child.a}'
print('Bug fix verified: parent.a =', parent.a, ', parent.child.a =', parent.child.a)

