import asdf
from asdf._display import render_tree

# Create a mock Time-like object with a custom __repr__
class MockTime:
    def __init__(self, value):
        self._tag = 'asdf://example.org/tags/time-1.0.0'
        self.value = value

    def __repr__(self):
        return f'MockTime({self.value!r})'

    def __asdf_traverse__(self):
        return {'value': self.value}

# Create a tree with the mock Time object
tree = {
    'start_time': MockTime('2023-01-01T00:00:00.000'),
    'mid_time': MockTime('2023-01-01T00:30:00.000'),
    'end_time': MockTime('2023-01-01T01:00:00.000'),
}

# Render the tree
lines = render_tree(tree, max_rows=None, max_cols=None, show_values=True)
for line in lines:
    print(line)

